INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11401, 'Ezra 10:6', 'Ezra', 10, 6, '&nbsp;بيا هغه د خُدائ پاک د کور د مخې نه لاړو او د اِلياسب زوئ يهوحنان کوټې ته ورننوتلو، هلته يې شپه تېره کړه او د جلاوطنۍ خلقو په بې‌وفايۍ يې خفګان کولو، او په دې وجه يې خوراک څښاک نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11402, 'Ezra 10:7', 'Ezra', 10, 7, '&nbsp;ټول يروشلم او يهوداه ته يو پېغام ولېږلے شو چې هغه ټول خلق دې په يروشلم کښې راغونډ شى چې کوم د جلاوطنۍ نه راواپس شوى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11403, 'Ezra 10:8', 'Ezra', 10, 8, '&nbsp;دا د خلقو د مشرانو حُکم وو. کۀ څوک په درېو ورځو کښې رانۀ غلو، نو د هغۀ ټول جائيداد به ضبط کړے شى او نور به دا حق نۀ لرى چې هغه د جلاوطنو د قبيلې نه وګڼلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11404, 'Ezra 10:9', 'Ezra', 10, 9, '&nbsp;په درېو ورځو کښې، د نهمې مياشتې په شلمه ورځ، هغه ټول سړى يروشلم ته راغلل کوم چې د يهوداه او بنيامين په علاقه کښې اوسېدل او د خُدائ پاک د کور د جرګې په ځائ کښې راغونډ شول. او په هغه وخت کښې دروند باران ورېدلو، د باران او د دې مسئلې په وجه هر يو کس رپېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11405, 'Ezra 10:10', 'Ezra', 10, 10, '&nbsp;عزرا اِمام ودرېدو او هغوئ ته يې وفرمائيل، ”تاسو بې‌وفا وئ او د غېرو قومونو د ښځو سره د ودونو په وجه مو بنى اِسرائيليان ګناهګار کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11406, 'Ezra 10:11', 'Ezra', 10, 11, '&nbsp;نو اوس مالِک خُدائ د خپل پلار نيکۀ خُدائ پاک ته د خپلو ګناهونو اِقرار وکړئ او هغه کار کوئ چې هغه پرې رضا کيږى. د پردى مُلک د هغه خلقو نه خپل ځانونه جدا کړئ چې کوم زمونږ په مُلک کښې اوسيږى او د غېرو قومونو د ښځو نه ځان خلاص کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11407, 'Ezra 10:12', 'Ezra', 10, 12, '&nbsp;نو ټولې ګڼې په جواب کښې چغه کړه، ”تۀ صحيح خبره کوې او چې څۀ وائې نو مونږ به هغه هر څۀ وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11408, 'Ezra 10:13', 'Ezra', 10, 13, '&nbsp;خو هغوئ دا هم ووئيل، ”ګڼه ډېره لويه ده او دا د باران موسم دے. مونږ دلته په داسې کولاو ځائ کښې نۀ شُو ودرېدے. دا داسې کار نۀ دے چې په يو دوو ورځو کښې وشى، ځکه چې په دې ګناه کښې زمونږ ډېر کسان شامل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11409, 'Ezra 10:14', 'Ezra', 10, 14, '&nbsp;زمونږ آفسران دې زمونږ ټولو په ځائ کار وکړى. بيا هغه هر يو دې چې د غېر قوم ښځه لرى هغه دې په يو مقرر وخت باندې د مشرانو او د خپل ښار د قاضيانو سره راشى. نو د دې معاملې په حقله به د خُدائ پاک قهر سوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11410, 'Ezra 10:15', 'Ezra', 10, 15, '&nbsp;صرف د عساهيل زوئ يونتن، د تِقوه زوئ يحزياه د دې منصوبې مخالفت وکړو، مسلام او يو ليوى سبتى ورسره په دې کښې ملګرى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11411, 'Ezra 10:16', 'Ezra', 10, 16, '&nbsp;د جلاوطنۍ نه راواپس شوو کسانو دا منصوبه منظوره کړه، نو عزرا اِمام د ډلو د مشرانو نه سړى مقرر کړل او د هغوئ نومونه يې وليکل. د لسمې مياشتې په وړومبۍ ورځ هغوئ تفتيش شروع کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11412, 'Ezra 10:17', 'Ezra', 10, 17, '&nbsp;او په ورپسې درېو مياشتو کښې هغوئ د هغه ټولو معامِلو معلومات وکړو چې کومو سړو د غېرو قومونو د ښځو سره ودونه کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11413, 'Ezra 10:18', 'Ezra', 10, 18, '&nbsp;دا د هغه سړو نومونه دى چا چې د غېرو قومونو ښځې کړې وې، د هغه اِمامانو نومونه د قبيلې په حِساب سره ليکلے شوى دى: د يشوَع ډله او د هغۀ د وروڼو چې د يوصدق زامن وُو: معسياه، اِلى‌عزر، يريب او جدلياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11414, 'Ezra 10:19', 'Ezra', 10, 19, '&nbsp;هغوئ دا قسم وکړو چې خپلو ښځو له به طلاق ورکړى او د خپلو د ګناه د تاوان د نذرانو دپاره يې د يو يو ګډ نذرانه پېش کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11415, 'Ezra 10:20', 'Ezra', 10, 20, '&nbsp;د اِمير ډله: حنانى او زبدياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11416, 'Ezra 10:21', 'Ezra', 10, 21, '&nbsp;د حارِم ډله: معسياه، الياس، سمعياه، يحى‌ايل او عُزياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11417, 'Ezra 10:22', 'Ezra', 10, 22, '&nbsp;د فشحور ډله: اليوعينى، معسياه، اِسمٰعيل، نتنى‌ايل، يوزبد او اِلعاسه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11418, 'Ezra 10:23', 'Ezra', 10, 23, '&nbsp;ليويان: يوزبد، سِمعى، قلاياه (چې قليتاه هم بللے شو)، فتحياه، يهوداه او اِلى‌عزر،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11419, 'Ezra 10:24', 'Ezra', 10, 24, '&nbsp;موسيقاران: اِلياسب، د خُدائ پاک د کور څوکيداران: سلوم، طلم او اورى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11420, 'Ezra 10:25', 'Ezra', 10, 25, '&nbsp;نور کسان: د پرعوس ډله: رمياه، يزياه، مُلکياه، ميامين، اِلى‌عزر، مُلکياه او بناياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11421, 'Ezra 10:26', 'Ezra', 10, 26, '&nbsp;د عيلام ډله: متنياه، زکرياه، يحى‌ايل، عبدى، يريموت او الياس،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11422, 'Ezra 10:27', 'Ezra', 10, 27, '&nbsp;د زتُو ډله: اليوعينى، اِلياسب، متنياه، يريموت، زاباد او عزيزا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11423, 'Ezra 10:28', 'Ezra', 10, 28, '&nbsp;د ببى ډله: يهوحنان، حننياه، زبى، عتلى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11424, 'Ezra 10:29', 'Ezra', 10, 29, '&nbsp;د بانى ډله: مسلام، ملوک، عداياه، يسوب، سيال او يريموت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11425, 'Ezra 10:30', 'Ezra', 10, 30, '&nbsp;د پخت موآب ډله: عدنا، کُلال، بناياه، معسياه، متنياه، بضلى‌اېل، بِنوئى او منسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11426, 'Ezra 10:33', 'Ezra', 10, 33, '&nbsp;د حاشوم ډله: متنى، متتاه، زاباد، اليفلط، يريمى، منسى او سِمعى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11427, 'Ezra 10:43', 'Ezra', 10, 43, '&nbsp;د نبو ډله: يعى‌ايل، متتياه، زاباد، زبينا، يدى، يوايل او بناياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11428, 'Ezra 10:44', 'Ezra', 10, 44, '&nbsp;دې هر يو سړى د غېرو قومونو ښځې لرلې او د څۀ سړو د دې ښځو نه بچى هم پېدا شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11429, 'Nehemiah 1:1', 'Nehemiah', 1, 1, '&nbsp;دا د حکلياه د زوئ د حضرت نحمياه کلام دے. کله چې ارتخششتا د فارس بادشاه وو نو د هغۀ د بادشاهۍ په شلم کال د کِسليو په مياشت کښې زۀ يعنې حضرت نحمياه په مرکزى ښار سوسه کښې وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11430, 'Nehemiah 1:2', 'Nehemiah', 1, 2, '&nbsp;زما ورور حنانى د يهوداه د يو څو سړو سره راورسېدو او ما د هغوئ نه د يروشلم او د هغه يهوديانو په حقله تپوس وکړو کوم چې د بابل د جلاوطنۍ نه راواپس شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11431, 'Nehemiah 1:3', 'Nehemiah', 1, 3, '&nbsp;هغوئ ما ته ووئيل چې کوم کسان د جلاوطنۍ نه بچ شوى وُو او د يهوداه صُوبې ته واپس راغلى وُو هغوئ د لوئ تکليف او بې‌عزتۍ سره مخ وُو. هغوئ ما ته دا هم ووئيل چې د يروشلم دېوالونه تر اوسه پورې مات پراتۀ دى او د دې دروازې د هغه وخت نه بيا نۀ دى جوړې شوې چې د کوم وخت نه هغه په اور سوزولے شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11432, 'Nehemiah 1:4', 'Nehemiah', 1, 4, '&nbsp;کله چې زۀ د دې هر څۀ نه خبر شوم، نو زۀ کښېناستم او ومې ژړل. څو ورځې زۀ غمژن وم او خوراک مې نۀ کولو. ما د آسمان خُدائ پاک ته سوال وکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11433, 'Nehemiah 1:5', 'Nehemiah', 1, 5, '&nbsp;او ما ووئيل، ”اے مالِکه خُدايه، د آسمان خُدايه پاکه، اے عظيمه او د رُعب خُدايه پاکه، تۀ د هغه چا سره خپل د رحم لوظ پوره کوې چې څوک درسره مينه کوى او ستا حُکمونه منى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11434, 'Nehemiah 1:6', 'Nehemiah', 1, 6, '&nbsp;مالِکه خُدايه، ما ته وګوره او زما سوال واوره، لکه څنګه چې زۀ ستا د خِدمتګارانو يعنې بنى اِسرائيلو دپاره شپه او ورځ دُعا کوم. زۀ دا اِقرار کوم چې مونږ بنى اِسرائيلو ګناه کړې ده. ما او زما پلار نيکۀ ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11435, 'Nehemiah 1:7', 'Nehemiah', 1, 7, '&nbsp;مونږ ستا خِلاف بدعملې کړې ده او تا چې څۀ حُکم کړے وو په هغې مو عمل نۀ دے کړے. تا چې د خپل خِدمتګار موسىٰ په ذريعه کوم قانون مونږ له راکړے وو په هغې مو عمل نۀ دے کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11436, 'Nehemiah 1:8', 'Nehemiah', 1, 8, '&nbsp;تۀ اوس هغه څۀ راياد کړه چې خپل خِدمت کوونکى موسىٰ ته دې فرمائيلى وُو چې کۀ تاسو بنى اِسرائيلو ما سره بې‌وفائى وکړه، نو زۀ به تاسو په نورو قومونو کښې خوارۀ وارۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11437, 'Nehemiah 1:9', 'Nehemiah', 1, 9, '&nbsp;خو کۀ بيا تاسو ما ته راوګرځېدئ او زما په حُکمونو عمل کوئ، نو زۀ به تاسو واپس هغه ځائ ته راولم کوم ځائ چې ما د خپل نوم د درناوى دپاره خوښ کړے دے، کۀ تاسو د دُنيا د يو سر نه تر بل سره پورې هم خوارۀ وارۀ يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11438, 'Nehemiah 1:10', 'Nehemiah', 1, 10, '&nbsp;مالِکه خُدايه، دا ستا خِدمتګاران او ستا خپل خلق دى. تا هغوئ د خپل لوئ طاقت او قوت سره په بيعه آزاد کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11439, 'Nehemiah 1:11', 'Nehemiah', 1, 11, '&nbsp;مالِکه خُدايه، اوس زما سوال واوره او د خپلو نورو ټولو خِدمتګارانو دُعاګانې واوره چې چا ته ستا د نوم په درناوى کولو کښې خوشحالى ملاويږى. او ما له کاميابى راکړه او داسې بادشاه نن په ما مِهربانه کړه. د هغۀ په زړۀ کښې دا خبره واچوه چې په ما رحم وکړى.“ په هغه وخت کښې زۀ د بادشاه ساقى وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11440, 'Nehemiah 2:1', 'Nehemiah', 2, 1, '&nbsp;د ارتخششتا بادشاه د بادشاهۍ په شلم کال د نيسان په مياشت کښې په کوم وخت چې بادشاه له مے راغلل، نو ما مے واخستل او بادشاه له مې ورکړل. زۀ د هغۀ په حضور کښې د دې نه مخکښې هيڅکله نۀ وم خفه شوے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11441, 'Nehemiah 2:2', 'Nehemiah', 2, 2, '&nbsp;نو ځکه هغۀ تپوس وکړو، ”تۀ ولې دومره غمژن يې؟ تۀ خو بيمار هم نۀ يې، ما ته پته ده چې تۀ ډېر سخت خفه يې.“ زۀ ډېر زيات يرېدم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11442, 'Nehemiah 2:3', 'Nehemiah', 2, 3, '&nbsp;او جواب مې ورکړو، ”بادشاه سلامت، خُدائ دې تا له ډېر عُمر درکړى. زۀ به ولې خفه نۀ يم چې په کوم ښار کښې زما پلار نيکۀ ښخ شوى دى هغه تباه شوے دے او د هغې دروازې په اور تباه شوې دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11443, 'Nehemiah 2:4', 'Nehemiah', 2, 4, '&nbsp;بادشاه را نه تپوس وکړو، ”تۀ څۀ غواړې؟“ نو ما د آسمانونو خُدائ پاک ته سوال وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11444, 'Nehemiah 2:5', 'Nehemiah', 2, 5, '&nbsp;او بيا مې بادشاه ته ووئيل، ”بادشاه سلامت، کۀ تۀ په ما باندې مِهربانى کول غواړې او دا چې زما درخواست منظور کړې، نو ما له دا اجازت راکړه چې زۀ يهوداه ته لاړ شم، نو چې داسې زۀ هغه ښار بيا جوړ کړم چرته چې زما پلار نيکۀ ښخ شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11445, 'Nehemiah 2:6', 'Nehemiah', 2, 6, '&nbsp;نو بادشاه په هغه وخت کښې زما درخواست منظور کړو، چې مَلِکه د هغۀ په څنګ کښې ناسته وه. هغۀ زما نه تپوس وکړو چې د څومره وخت دپاره به ځې او بيا به کله واپس راځې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11446, 'Nehemiah 2:7', 'Nehemiah', 2, 7, '&nbsp;بيا ما هغۀ ته ووئيل چې په ما دا مِهربانى وکړه چې ما له د فرات سيند نمرپرېواتۀ طرف ته د صُوبې د حکمرانانو دپاره خطونه راکړه، چې په کښې هغوئ ته دا ليکلى شوى وى چې ما له اجازت راکړى چې د هغوئ په مُلک کښې يهوداه ته په خېر سره سفر وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11447, 'Nehemiah 2:8', 'Nehemiah', 2, 8, '&nbsp;ما د شاهى ځنګلو څوکيدار آسف دپاره هم يو خط وغوښتو، چې هغۀ ته په کښې ليکلى شوى وُو چې د هغه قلعې د دروازو دپاره چې د خُدائ پاک د کور حِفاظت کوى، د ښار د دېوالونو دپاره او د هغه کور دپاره ما له لرګى راکړى چې په کوم کښې به زۀ اوسېدم. ما چې څۀ غوښتى وُو نو بادشاه ما له هغه هر څۀ راکړل، ځکه چې خُدائ پاک په ما مِهربانه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11448, 'Nehemiah 2:9', 'Nehemiah', 2, 9, '&nbsp;نو بادشاه ما سره يو څو فوجى آفسران او په آسونو د سوارو کسانو يوه ډله ولېږله او زۀ د نمرپرېواتۀ طرف ته فرات په سفر باندې روان شوم. هلته مې حکمرانانو له د بادشاه خطونه ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11449, 'Nehemiah 2:10', 'Nehemiah', 2, 10, '&nbsp;خو د بيت‌حورون ښار سنبلط، او طوبياه چې هغه د عمون صُوبې يو آفسر وو، خبر شو چې څوک راغلى دى چې د بنى اِسرائيلو د فائدې دپاره کار کوى، نو هغوئ ډېر زيات خفه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11450, 'Nehemiah 2:11', 'Nehemiah', 2, 11, '&nbsp;زۀ يروشلم ته لاړم او تر درېو ورځو پورې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11451, 'Nehemiah 2:12', 'Nehemiah', 2, 12, '&nbsp;ما هيچا ته هغه خبره ونۀ کړه چې کومه خُدائ پاک زما په زړۀ کښې د يروشلم په حقله اچولې وه. بيا په نيمه شپه زۀ پاڅېدم او بهر لاړم، يو څو ملګرى مې ځان سره کړل. مونږ صِرف يو ځناور د ځان سره بوتلو، دا هغه خر وو چې په کوم زۀ سور وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11452, 'Nehemiah 2:13', 'Nehemiah', 2, 13, '&nbsp;کله چې زۀ د ښار نه روان شوم نو تر اوسه پورې شپه وه. د وادۍ په دروازه باندې ووتلم او د ګيدړ کوهى نه تېر شوم او د ګند دروازې ته لاړم. کله چې زۀ روان وم، نو ما د ښار غورزېدلى دېوالونه او هغه دروازې وليدې کومې چې په اور تباه شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11453, 'Nehemiah 2:14', 'Nehemiah', 2, 14, '&nbsp;نو بيا زۀ د فوارې دروازې ته او د بادشاه تالاب ته لاړم، خو په کوم خر باندې چې ما سورلى کوله نو هغۀ د تېرېدو لار پېدا نۀ کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11454, 'Nehemiah 2:15', 'Nehemiah', 2, 15, '&nbsp;بيا زۀ لاندې د قِدرون وادۍ ته لاړم او په خر باندې سور وم، دېوال ته مې کتل. بيا زۀ په هغه لار راواپس شوم چې په کومه راغلے وم او د وادۍ په دروازه باندې واپس ښار ته لاړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11455, 'Nehemiah 2:16', 'Nehemiah', 2, 16, '&nbsp;د هغې علاقې يو آفسر ته هم دا پته ونۀ لګېده چې زۀ چرته وم يا مې څۀ کول. تر اوسه پورې ما يهوديانو، اِمامانو، مشرانو، آفسرانو، يا بل چا ته هيڅ نۀ وُو وئيلى چې څوک به دا کار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11456, 'Nehemiah 2:17', 'Nehemiah', 2, 17, '&nbsp;خو بيا ما هغوئ ته ووئيل، ”ګورئ مونږ په دې وجه په تکليف کښې يُو چې يروشلم تباه شوے دے او د دې دروازې سوزولے شوې دى. راځئ چې د يروشلم دېوالونه بيا جوړ کړُو او د دې بې‌عزتۍ نه ځان خلاص کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11457, 'Nehemiah 2:18', 'Nehemiah', 2, 18, '&nbsp;او ما هغوئ ته ووئيل چې خُدائ پاک زما څنګه مل وو او هغه څۀ مې ورته ووئيل چې ما ته بادشاه وئيلى وُو. نو هغوئ په جواب کښې ووئيل، ”راځئ چې د دېوالونو په جوړولو بيا شروع وکړُو.“ او هغوئ د نېکۍ په دې کار کولو باندې شروع وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11458, 'Nehemiah 2:19', 'Nehemiah', 2, 19, '&nbsp;کله چې سنبلط حورونى، عمونى طوبياه او جشم نومې يو عربے زمونږ د منصوبې نه خبر شول، نو هغوئ په مونږ پورې ټوقې او مسخرې وکړې او وې وئيل، ”تاسو دا څۀ شروع کړى دى؟ ولې تاسو د بادشاه خِلاف بغاوت کول غواړئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11459, 'Nehemiah 2:20', 'Nehemiah', 2, 20, '&nbsp;ما جواب ورکړو، ”د آسمان خُدائ پاک به مونږ له کاميابى راکړى. مونږ د هغۀ خِدمت کوونکى يُو او مونږ کار شروع کوُو. خو تاسو په يروشلم کښې د جائيداد لرلو هيڅ حق نۀ لرئ، او نۀ حِصه لرئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11460, 'Nehemiah 3:1', 'Nehemiah', 3, 1, '&nbsp;بيا مشر اِمام اِلياسب او د هغۀ ملګرو اِمامانو د ګډو دروازه بيا جوړه کړه، هغوئ هغه وقف کړه او دروازې يې په خپل ځائ ولګولې. هغوئ د سلو مينارو پورې دېوال او د حنن‌ايل ميناره پورې دېوال وقف کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11461, 'Nehemiah 3:2', 'Nehemiah', 3, 2, '&nbsp;د يريحو خلقو ورپسې برخه جوړه کړه. د اِمرى زوئ زکور بله برخه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11462, 'Nehemiah 3:3', 'Nehemiah', 3, 3, '&nbsp;د سناآه قبيلې د کبانو دروازه جوړه کړه. هغوئ تيرونه او دروازې په خپل ځائ باندې ولګولې، د دروازې د تالا کولو دپاره يې سيخونه او زنځيرونه ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11463, 'Nehemiah 3:4', 'Nehemiah', 3, 4, '&nbsp;د اورِياه زوئ او د هقوض نمسى مريموت ورپسې برخه جوړه کړه. د برکياه زوئ او د مشيزب‌ايل نمسى مسلام ورپسې برخه جوړه کړه. د بعنه زوئ صدوق بله برخه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11464, 'Nehemiah 3:5', 'Nehemiah', 3, 5, '&nbsp;د تقوع سړو ورپسې برخه جوړه کړه، خو د هغوئ مشرانو د هغه کار کولو نه اِنکار وکړو کوم کار چې هغوئ ته خپلو ټېکدارانو حواله کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11465, 'Nehemiah 3:6', 'Nehemiah', 3, 6, '&nbsp;د فاسح زوئ يويدع او د بسودياه زوئ مسلام د يسانه دروازه بيا جوړه کړه. هغوئ تيرونه او دروازې په خپلو ځايونو کښې ولګول او د تاله کولو دپاره يې په دروازه کښې اړمونه او کُنډې ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11466, 'Nehemiah 3:7', 'Nehemiah', 3, 7, '&nbsp;د جبعون ملطياه، د مرونوت يدون او د جبعون او مصفاه سړو ورپسې برخه جوړه کړه چې د نمرپرېواتۀ طرف ته فرات د حکمران کور پورې حِصه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11467, 'Nehemiah 3:8', 'Nehemiah', 3, 8, '&nbsp;د حرهياه زوئ عُزى‌اېل زرګر ورپسې برخه جوړه کړه. حننياه عطر جوړوونکى ورپسې برخه جوړه کړه، چې د پلن دېوال پورې حِصه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11468, 'Nehemiah 3:9', 'Nehemiah', 3, 9, '&nbsp;د يروشلم د نيمې ضِلعې حکمران د حُور زوئ رفاياه ورپسې برخه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11469, 'Nehemiah 3:10', 'Nehemiah', 3, 10, '&nbsp;د حرومف زوئ يدعياه ورپسې برخه جوړه کړه، کومه چې د هغۀ د خپل کور سره نزدې وه. د حسبنياه زوئ حطوش ورپسې برخه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11470, 'Nehemiah 3:11', 'Nehemiah', 3, 11, '&nbsp;د حارِم زوئ مُلکياه او د پخت موآب زوئ حسوب دوئ دواړو ورپسې برخه او د تنور ميناره يې جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11471, 'Nehemiah 3:12', 'Nehemiah', 3, 12, '&nbsp;د يروشلم د نورې نيمې ضِلعې حکمران يعنې د هلوحيس زوئ سلوم ورپسې برخه جوړه کړه. د هغۀ لوڼو په دې کار کښې د هغۀ مدد کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11472, 'Nehemiah 3:13', 'Nehemiah', 3, 13, '&nbsp;حنون او د زنوح ښار اوسېدونکو د وادۍ دروازه بيا جوړه کړه. هغوئ هغه دروازې په خپلو خپلو ځايونو باندې ولګولې، هغوئ د دروازې تالا کولو دپاره په دې کښې سيخونه او زنځيرونه ولګول او د ګند دروازې پورې هغوئ پينځۀ سوه ګزه دېوال بيا جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11473, 'Nehemiah 3:14', 'Nehemiah', 3, 14, '&nbsp;د بيت‌هکرم ضِلعې حکمران د ريکاب زوئ مُلکياه د ګند دروازه بيا جوړه کړه. هغۀ دروازې په خپلو ځايونو باندې ولګولې او د دروازې تالا کولو دپاره يې په کښې سيخونه او زنځيرونه ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11474, 'Nehemiah 3:15', 'Nehemiah', 3, 15, '&nbsp;د مصفاه ضِلعې حکمران د کولحوزه زوئ سلوم د فوارې دروازه بيا جوړه کړه. هغۀ د دروازې دپاسه چت جوړ کړو، دروازې يې په خپل ځائ باندې ولګولې او سيخونه او زنځيرونه يې په کښې ولګول. د سِلح تالاب سره د شاهى باغ سره نزدې هغۀ دېوال جوړ کړو، دا تر هغه ځائ پورې وو چرته چې د داؤد د ښار نه لاندې پوړۍ کوزې شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11475, 'Nehemiah 3:16', 'Nehemiah', 3, 16, '&nbsp;د بيت‌صور د نيمې ضِلعې حکمران د عُزبق زوئ نحمياه ورپسې برخه جوړه کړه، چې دا د داؤد د خاندان د قبرستان، تالاب او د فوجيانو کورونو پورې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11476, 'Nehemiah 3:17', 'Nehemiah', 3, 17, '&nbsp;دې ليويانو د هغه دېوال نورې برخې بيا جوړې کړې: د بانى زوئ رحُوم ورپسې برخه جوړه کړه، د قعيله د نيمې ضِلعې حکمران، حسبياه د خپلې ضِلعې د طرفه ورپسې برخه جوړه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11477, 'Nehemiah 3:18', 'Nehemiah', 3, 18, '&nbsp;د قعيله د نورې نيمې ضِلعې د حکمران د حنداد زوئ باوى ورپسې برخه جوړه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11478, 'Nehemiah 3:19', 'Nehemiah', 3, 19, '&nbsp;د مصفاه حکمران د يشوَع زوئ ايصر د وسلې د ګودام په مخکښې ورپسې حِصه جوړه کړه، دا تر هغه ځائ پورې وه چرته چې دېوال تاويږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11479, 'Nehemiah 3:20', 'Nehemiah', 3, 20, '&nbsp;د زبى زوئ باروک ورپسې برخه جوړه کړه، دا تر هغه ځائ پورې وه چرته چې د مشر اِمام اِلياسب کور ته د ننوتلو دروازه وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11480, 'Nehemiah 3:21', 'Nehemiah', 3, 21, '&nbsp;د اورِياه زوئ او د هقوض نمسى مريموت ورپسې برخه جوړه کړه، چې دا د اِلياسب د کور تر آخرى سر پورې رسېدلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11481, 'Nehemiah 3:22', 'Nehemiah', 3, 22, '&nbsp;دې اِمامانو د دېوال يو څو نورې برخې بيا جوړې کړې: د يروشلم د ګېرچاپېره علاقې نه اِمامانو ورپسې برخه بيا جوړه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11482, 'Nehemiah 3:23', 'Nehemiah', 3, 23, '&nbsp;بنيامين او د حسوب ورپسې برخه جوړه کړه، کومه چې د هغوئ کورونو ته مخامخ وه، د معسياه زوئ او د عننياه نمسى عزرياه ورپسې برخه جوړه کړه، کومه چې د هغۀ د کور مخې ته وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11483, 'Nehemiah 3:24', 'Nehemiah', 3, 24, '&nbsp;د حنداد زوئ بِنوئى ورپسې برخه جوړه کړه، چې دا د عزرياه د کور نه واخله د دېوال د ګوټ پورې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11484, 'Nehemiah 3:27', 'Nehemiah', 3, 27, '&nbsp;د تقوع سړو ورپسې برخه جوړه کړه، د هغوئ دوېمه برخه، د هغه ځائ نه واخله چې د خُدائ پاک د کور د څوکيدارۍ د لوئې مينارې مخامخ وه د هغې نه واخله تر عوفل سره نزدې دېوال پورې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11485, 'Nehemiah 3:28', 'Nehemiah', 3, 28, '&nbsp;د اِمامانو يوې قبيلې ورپسې برخه جوړه کړه، چې شمالى طرف ته د آسونو د دروازې نه تلې وه، هر يو د خپل کور په مخکښې حِصه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11486, 'Nehemiah 3:29', 'Nehemiah', 3, 29, '&nbsp;د اِمير زوئ صدوق ورپسې برخه جوړه کړه، کومه چې د هغۀ کور په مخکښې وه. د نمرخاتۀ طرف دروازې څوکيدار د سکانياه زوئ سمعياه ورپسې برخه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11487, 'Nehemiah 3:30', 'Nehemiah', 3, 30, '&nbsp;د شلمياه زوئ حننياه او د صلف شپږم زوئ حنون ورپسې دوېمه برخه جوړه کړه. د برکياه زوئ مسلام ورپسې برخه جوړه کړه، کومه چې د هغۀ کور مخې ته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11488, 'Nehemiah 3:31', 'Nehemiah', 3, 31, '&nbsp;مُلکياه زرګر ورپسې برخه جوړه کړه، دا تر هغې پورې وه چې کوم کور د خُدائ پاک د کور کاريګرو او سوداګرو استعمالولو، کوم چې د حاضرۍ دروازې سره وو، دا د هغه کوټې سره نزدې وو چې د شمالى نمرخاتۀ طرف ته د ګوټ دېوال دپاسه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11489, 'Nehemiah 3:32', 'Nehemiah', 3, 32, '&nbsp;زرګرانو او سوداګرو آخرى برخه جوړه کړه، دا د ګوټ سره د کوټې نه واخله د ګډو د دروازې پورې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11490, 'Nehemiah 4:1', 'Nehemiah', 4, 1, '&nbsp;کله چې سنبلط خبر شو چې مونږ يهوديانو دېوال جوړول بيا شروع کړى دى، نو هغه سخت غصه شو او مونږ پورې يې خندا شروع کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11491, 'Nehemiah 4:2', 'Nehemiah', 4, 2, '&nbsp;د خپلو ملګرو او د سامرى فوجيانو په مخکښې يې ووئيل، ”دا بدبخته يهوديان چې څۀ کوى د هغې په حقله يې څۀ خيال دے؟ د هغوئ اراده د ښار بيا جوړولو ده څۀ؟ ولې د هغوئ خيال دا دے چې صِرف د يو څو قربانو پېش کولو په وجه به هغوئ هغه دېوال په يوه ورځ کښې جوړ کړى؟ هغوئ د سوزېدلو کاڼو او د ملبې د ډېرى نه د عمارت کاڼى جوړولے شى څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11492, 'Nehemiah 4:3', 'Nehemiah', 4, 3, '&nbsp;طوبياه هلته د هغۀ په څنګ کښې ولاړ وو او دا خبره يې وکړه، ”هغوئ څۀ قسم دېوال جوړولے شى؟ داسې چې يو لومبړه يې هم راغورزولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11493, 'Nehemiah 4:4', 'Nehemiah', 4, 4, '&nbsp;ما دُعا وکړه، ”خُدايه پاکه، د هغوئ خندا واوره چې په مونږ پورې يې کوى، د هغوئ کنځل دې هم هغوئ ته بلا شى. هغوئ دې وتښتولے شى او پردى مُلک ته دې قېديان بوتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11494, 'Nehemiah 4:5', 'Nehemiah', 4, 5, '&nbsp;هغوئ چې کوم بد عمل کوى هغه مۀ معاف کوه او د هغوئ ګناهونه مۀ هېروه، ځکه چې مونږ کله دېوال جوړولو نو هغوئ زمونږ بې‌عزتى کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11495, 'Nehemiah 4:6', 'Nehemiah', 4, 6, '&nbsp;نو مونږ د دېوال په جوړولو باندې لګيا وُو او دا دېوال زر د نيم اوچتوالى پورې جوړ شو، ځکه چې خلقو به په شوق سره د دې کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11496, 'Nehemiah 4:7', 'Nehemiah', 4, 7, '&nbsp;خو کله چې سنبلط، طوبياه، او د عربو، د عمون او د اشدود خلقو واورېدل چې د يروشلم د دېوال د بيا جوړېدلو کار شروع شوے وو او چې د دېوال غورزېدلى ځايونه بيا جوړيږى نو هغوئ سخت غصه شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11497, 'Nehemiah 4:8', 'Nehemiah', 4, 8, '&nbsp;نو هغوئ ټولو دا منصوبه جوړه کړه چې راشى او په يروشلم باندې حمله وکړى او ګډوډى پېدا کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11498, 'Nehemiah 4:9', 'Nehemiah', 4, 9, '&nbsp;خو مونږ خپل خُدائ پاک ته سوال وکړو او د هغوئ خِلاف مو شپه او ورځ په څوکيدارۍ باندې سړى ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11499, 'Nehemiah 4:10', 'Nehemiah', 4, 10, '&nbsp;د يهوداه خلقو يوه سندره لرله او هغوئ ووئيله، ”مونږ مزدوران کمزورى شوى يُو، دومره ماتې خَښتې به څنګه اوچتوُو. مونږ دا دېوال نن څنګه جوړ کړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11500, 'Nehemiah 4:11', 'Nehemiah', 4, 11, '&nbsp;زمونږ د دشمنانو خيال دا وو چې مونږ به خپل دشمنان ونۀ ګورو او نۀ به تر هغې پورې دا پته راته ولګى چې څۀ کيږى چې ترڅو پورې هغوئ مونږ ته رارسېدلى نۀ وى، مونږ به ووژنى او زمونږ کار به بند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');